-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.usage_figure(v bigint, students bigint)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case when students between 1 and 4 then to_jsonb('<5'::text) else to_jsonb(coalesce(v, 0)) end;
$function$;

grant execute on function public.usage_figure(v bigint, students bigint) to service_role;
